// Money.js (Frontend - React)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Money.css'; // Create this CSS file for styling

function Money() {
    const [senderEmail, setSenderEmail] = useState(localStorage.getItem('email'));
    const [recipientEmail, setRecipientEmail] = useState('');
    const [amount, setAmount] = useState('');
    const [message, setMessage] = useState('');
    const [senderBalance, setSenderBalance] = useState(null);  // Add state for sender balance



    useEffect(() => {
        const fetchSenderBalance = async () => {  // Fetch sender balance initially
            if (senderEmail) {  // Ensure senderEmail exists before fetching balance
                try {
                    const response = await axios.get(`http://localhost:8000/savings/${senderEmail}`);
                    setSenderBalance(response.data.balance);
                } catch (error) {
                    console.error("Error fetching balance:", error);
                    setMessage('Error fetching balance. Please try again.');
                }
            }
        };

        fetchSenderBalance();  // Call the function to fetch the balance
    }, [senderEmail]);  // Run effect whenever senderEmail changes




    const handleTransfer = async () => {
        try {
            if (parseFloat(amount) > senderBalance) {  // Check if sufficient balance
                setMessage("Insufficient funds");
                return;
            }
            const response = await axios.post('http://localhost:8000/transfer', {
                senderEmail,
                recipientEmail,
                amount: parseFloat(amount),
            });
            setMessage(response.data.message);
            setSenderBalance(response.data.senderBalance);
            setRecipientEmail('');  // Clear input fields if needed
            setAmount('');


        } catch (error) {
            if (error.response && error.response.data && error.response.data.message) {
                setMessage(error.response.data.message); // More specific error message
            } else {
                setMessage('Error transferring money. Please try again.');
            }

            console.error("Transfer error:", error);
        }
    };

    return (
        <>
        <div className="money-container">
             <p>Your Balance: {senderBalance}</p> 
            <h2>Transfer Money</h2>
            <input
                type="email"
                placeholder="Recipient's Email"
                value={recipientEmail}
                onChange={(e) => setRecipientEmail(e.target.value)}
                required
            />
            <input
                type="number"
                placeholder="Amount"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                required
            />
            <button onClick={handleTransfer}>Transfer</button>
            {message && <p>{message}</p>}
        </div>
        </>
    );
}

export default Money;
